class Solution:
    def lastMarkedNodes(self, edges: list[list[int]]) -> list[int]:
        from collections import deque
        n = len(edges) + 1
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        def bfs_farthest(start: int):
            dist = [-1] * n
            dist[start] = 0
            q = deque([start])
            farthest = start
            while q:
                u = q.popleft()
                if dist[u] > dist[farthest]:
                    farthest = u
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u] + 1
                        q.append(v)
            return farthest, dist

        # Diameter endpoint 1
        u, _ = bfs_farthest(0)
        # Diameter endpoint 2 and distances from u
        v, dist_u = bfs_farthest(u)
        # Distances from v
        _, dist_v = bfs_farthest(v)

        ans = [0] * n
        for i in range(n):
            if dist_u[i] >= dist_v[i]:
                ans[i] = u
            else:
                ans[i] = v
        return ans

#include <vector>
#include <queue>

class Solution {
public:
    std::vector<int> lastMarkedNodes(std::vector<std::vector<int>>& edges) {
        int n = edges.size() + 1;
        std::vector<std::vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }

        auto bfs = [&](int start, std::vector<int>& dist) {
            std::fill(dist.begin(), dist.end(), -1);
            dist[start] = 0;
            std::queue<int> q;
            q.push(start);
            int farthest = start;
            while (!q.empty()) {
                int u = q.front(); q.pop();
                if (dist[u] > dist[farthest]) farthest = u;
                for (int v : adj[u]) {
                    if (dist[v] == -1) {
                        dist[v] = dist[u] + 1;
                        q.push(v);
                    }
                }
            }
            return farthest;
        };

        std::vector<int> dist_tmp(n);
        int u = bfs(0, dist_tmp);
        std::vector<int> dist_u(n);
        int v = bfs(u, dist_u);
        std::vector<int> dist_v(n);
        bfs(v, dist_v);

        std::vector<int> ans(n);
        for (int i = 0; i < n; ++i) {
            ans[i] = (dist_u[i] >= dist_v[i]) ? u : v;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] lastMarkedNodes(int[][] edges) {
        int n = edges.length + 1;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }

        int[] distTmp = new int[n];
        int u = bfs(0, adj, distTmp, n);
        int[] distU = new int[n];
        int v = bfs(u, adj, distU, n);
        int[] distV = new int[n];
        bfs(v, adj, distV, n);

        int[] ans = new int[n];
        for (int i = 0; i < n; i++) {
            ans[i] = (distU[i] >= distV[i]) ? u : v;
        }
        return ans;
    }

    private int bfs(int start, List<List<Integer>> adj, int[] dist, int n) {
        Arrays.fill(dist, -1);
        dist[start] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(start);
        int farthest = start;

        while (!q.isEmpty()) {
            int curr = q.poll();
            if (dist[curr] > dist[farthest]) farthest = curr;
            for (int nxt : adj.get(curr)) {
                if (dist[nxt] == -1) {
                    dist[nxt] = dist[curr] + 1;
                    q.offer(nxt);
                }
            }
        }
        return farthest;
    }
}

var lastMarkedNodes = function(edges) {
    const n = edges.length + 1;
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    function bfs(start, dist) {
        dist.fill(-1);
        dist[start] = 0;
        const q = [start];
        let head = 0;
        let farthest = start;

        while (head < q.length) {
            const u = q[head++];
            if (dist[u] > dist[farthest]) farthest = u;
            for (const v of adj[u]) {
                if (dist[v] === -1) {
                    dist[v] = dist[u] + 1;
                    q.push(v);
                }
            }
        }
        return farthest;
    }

    const distTmp = new Int32Array(n);
    const u = bfs(0, distTmp);
    const distU = new Int32Array(n);
    const v = bfs(u, distU);
    const distV = new Int32Array(n);
    bfs(v, distV);

    const ans = new Int32Array(n);
    for (let i = 0; i < n; i++) {
        ans[i] = (distU[i] >= distV[i]) ? u : v;
    }
    return Array.from(ans);
};
